INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129412, 'ruRU', '', 'Привет, $n. Знаешь ли ты, что Королевский пруд когда-то был домом для самых крупных и прекрасных рыб во всей Азсуне? Представители королевской семьи часто смотрели на воду, наблюдая за изящными движениями, пытаясь забыть о своих тяжёлых заботах.\n\nТеперь же... ох, что-то не так!', 24330),
(129421, 'ruRU', '', '$n, рад тебя видеть! Есть новости о том, что происходит?', 24330),
(129422, 'ruRU', '', 'Добро пожаловать в лавку! Совет уже высказался со своими выводами, $n?', 24330),
(129423, 'ruRU', '', 'Рад снова видеть тебя, $n. Пришёл поболтать? Ищешь припасы? А может, просто немного отдохнуть от... того, что там происходит.', 24330),
(129424, 'ruRU', '', 'Наша дверь всегда открыта, $n. Надеюсь, атмосфера здесь спокойнее, чем там, снаружи.', 24330),
(129425, 'ruRU', '', 'Здесь ты в безопасности, $n. Айндеру настойчиво следит за дверью с самого начала всего этого, но меня это не беспокоит.', 24330),
(129437, 'ruRU', '', 'Услышь крики отчаявшихся!', 24330),
(129438, 'ruRU', '', 'Пусть их агония накроет тебя!', 24330),
(129439, 'ruRU', '', 'Их мучения станут твоими собственными!', 24330),
(129440, 'ruRU', '', 'Жизнь и смерть... сплетены воедино!', 24330),
(129441, 'ruRU', '', 'Аах, узы, что связывают!', 24330),
(129442, 'ruRU', '', 'Чувствуешь ли ты тиски рока?', 24330),
(129465, 'ruRU', '', 'Как я служу, так и ты будешь служить!', 24330),
(129466, 'ruRU', '', 'Пусть этот храм станет твоей гробницей!', 24330),
(129467, 'ruRU', '', 'Не противься воле хозяина!', 24330),
(129468, 'ruRU', '', 'Твой дух принадлежит мне!', 24330),
(129469, 'ruRU', '', 'Я забираю тебя для хозяина!', 24330),
(129470, 'ruRU', '', 'Питайся, машина! Питайся!', 24330),
(129471, 'ruRU', '', 'Элуна не имеет власти здесь. Эта гробница принадлежит Легиону!', 24330),
(129472, 'ruRU', '', 'Смертные души... такие слабые, такие жалкие!', 24330),
(129473, 'ruRU', '', 'Машина поглощает всё!', 24330),
(129474, 'ruRU', '', 'Мне следовало быть сильнее. Скажи Тиранде... что мне жаль.', 24330),
(129475, 'ruRU', '', 'Я пыталась сопротивляться им, но не смогла. По крайней мере, теперь я свободна.', 24330),
(129476, 'ruRU', '', 'Благодарю вас, защитники. Молюсь, чтобы вы очистили тьму, что преследует этот храм.', 24330),
(129477, 'ruRU', '', 'Арилле, прошу! Не при гостях. Мы ещё не знаем, что это такое, и нет смысла строить предположения.', 24330),
(129478, 'ruRU', '', 'Присаживайся и отдохни. Мы знаем, что там, снаружи, может быть напряжённо, так что оставь свои тревоги у двери.', 24330),
(129479, 'ruRU', '', 'Ах, $n! Может, ты поможешь нам разрешить спор... Арилле и я спорили, закончил ли Совет свою оценку. Есть новости?', 24330),
(129480, 'ruRU', '', 'Ох нет! Разлила ещё один напиток. Никак не могу держать руки твёрдо из-за всего, что здесь происходит.', 24330),
(129481, 'ruRU', '', 'Надеюсь, у тебя всё хорошо, $n. А что до меня, то...', 24330),
(129482, 'ruRU', '', 'Иногда я думаю, услышим ли мы когда-нибудь ответ, почему всё это происходит...', 24330),
(129483, 'ruRU', '', 'Надеюсь, скоро мы получим новости. С последних прошло уже немало времени.', 24330),
(129484, 'ruRU', '', 'Всё это ожидание, чтобы узнать, что происходит, превращает меня в комок нервов.', 24330),
(129485, 'ruRU', '', 'Принёс какие-нибудь новости сегодня? Мы давно ничего не слышали.', 24330),
(129486, 'ruRU', '', 'Как дела снаружи, $n? Люди приходили и уходили весь день, но, похоже, никто толком ничего не знает.', 24330),
(129487, 'ruRU', '', 'Добро пожаловать! Люциан и я только что обсуждали недавние события. Есть для нас какие-нибудь новости?', 24330),
(129488, 'ruRU', '', 'Что там происходит? Шум становится всё громче. Надеюсь, мы скоро услышим какие-нибудь новости.', 24330),
(129489, 'ruRU', '', 'Смотри под ноги, $n! Слушай, а есть уже весточка от Совета?', 24330),
(129492, 'ruRU', '', 'Прошу прощения, если питомцы ведут себя беспокойно. Что-то их растревожило.', 24330),
(129493, 'ruRU', '', 'Будь осторожен. Питомцы ведут себя странно. Было бы разумно пока держаться подальше от загонов.', 24330),
(129494, 'ruRU', '', 'Ну-ну, мои великолепные звери! Скоро всё вернётся в норму... надеюсь.', 24330);
